// Example: A function that continuously generates data
function fastProducer(writableStream) {
  let count = 0;
  function generate() {
    while (count < 1000) {
      const canWrite = writableStream.write(`Data chunk ${count}\n`);
      count++;
      if (!canWrite) {
        // Handle backpressure
        writableStream.once('drain', generate);
        return;
      }
    }
    writableStream.end();
  }
  generate();
}

